begin;
select no_plan();
set local storage.allow_delete_query='true';
insert into auth.users(id,email) values ('11111111-1111-4111-8111-111111111111','a@example.test'),('22222222-2222-4222-8222-222222222222','b@example.test');
insert into public.pets(id,owner_id,name,species) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','A','Kedi'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','22222222-2222-4222-8222-222222222222','B','Kedi');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$insert into public.health_records(id,pet_id,kind,title,occurred_on,weight_kg) values ('cccccccc-cccc-4ccc-8ccc-cccccccccccc','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','weight','Kilo','2026-09-14',4.5)$$,'A creates weight');
select lives_ok($$insert into public.health_documents(pet_id,record_id,storage_path,file_name,mime_type,size_bytes) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','cccccccc-cccc-4ccc-8ccc-cccccccccccc','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa/dddddddd-dddd-4ddd-8ddd-dddddddddddd.pdf','a.pdf','application/pdf',10)$$,'A creates linked document');
select throws_ok($$update public.health_records set weight_kg=0$$,'23514',null,'reject zero weight');
select throws_ok($$update public.health_records set due_on='2026-09-13'$$,'23514',null,'reject reversed date');
select throws_ok($$update public.health_documents set size_bytes=10485761$$,'23514',null,'reject oversized metadata');
select throws_ok($$update public.health_documents set mime_type='text/html'$$,'23514',null,'reject unsafe mime');
select throws_ok($$update public.health_records set pet_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'$$,'23503',null,'DB rejects cross-owner pet');
select throws_ok($$update public.health_documents set record_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd'$$,'23503',null,'DB rejects missing record');
select is((select count(*)::int from public.health_records),1,'A reads health_records');
select results_eq($$update public.health_records set updated_at=now() returning owner_id$$,array['11111111-1111-4111-8111-111111111111'::uuid],'A updates health_records');
select throws_ok($$update public.health_records set owner_id='22222222-2222-4222-8222-222222222222'$$,'42501',null,'A cannot transfer health_records ownership');
select is((select count(*)::int from public.health_documents),1,'A reads health_documents');
select results_eq($$update public.health_documents set updated_at=now() returning owner_id$$,array['11111111-1111-4111-8111-111111111111'::uuid],'A updates health_documents');
select throws_ok($$update public.health_documents set owner_id='22222222-2222-4222-8222-222222222222'$$,'42501',null,'A cannot transfer health_documents ownership');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*)::int from public.health_records),0,'B cannot read A health_records');
select results_eq($$update public.health_records set updated_at=now() returning id$$,array[]::uuid[],'B cannot update A health_records');
select results_eq($$delete from public.health_records returning id$$,array[]::uuid[],'B cannot delete A health_records');
select is((select count(*)::int from public.health_documents),0,'B cannot read A health_documents');
select results_eq($$update public.health_documents set updated_at=now() returning id$$,array[]::uuid[],'B cannot update A health_documents');
select results_eq($$delete from public.health_documents returning id$$,array[]::uuid[],'B cannot delete A health_documents');
select throws_ok($$insert into public.health_records(owner_id,pet_id,kind,title,occurred_on) values ('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','exam','x','2026-09-14')$$,'42501',null,'B cannot forge record owner');
select throws_ok($$insert into public.health_records(pet_id,kind,title,occurred_on) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','exam','x','2026-09-14')$$,'23503',null,'B cannot use A pet');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$delete from public.health_records$$,'A deletes record');
select is((select record_id from public.health_documents),null::uuid,'record deletion preserves standalone document');
select lives_ok($$delete from public.health_documents$$,'A deletes document');
reset role;
set local role anon;
select throws_ok($$select * from public.health_records$$,'42501',null,'anon denied records');
select throws_ok($$select * from public.health_documents$$,'42501',null,'anon denied documents');
select * from finish();
rollback;
